// Package migrate runs versioned migrations against a MongoDB database and
// records which ones have been applied in the schema_migrations collection.
//
// Migrations are Go code, so they are compiled into the project's own runner
// binary: each generated migration file registers itself from init(), and the
// runner (generated by `gom init`) blank-imports the migrations package and
// calls Main.
package migrate

import (
	"context"
	"fmt"
	"sort"
	"sync"

	"go.mongodb.org/mongo-driver/mongo"
)

// Collection is where applied versions are recorded.
const Collection = "schema_migrations"

// Func is one direction of a migration.
type Func func(ctx context.Context, db *mongo.Database) error

// Migration is a single versioned change. Version is the timestamp prefix of
// the file that declares it (YYYYMMDDHHMMSS), which orders migrations.
type Migration struct {
	Version int64
	Name    string
	Up      Func
	Down    Func
}

var (
	mu       sync.Mutex
	registry = map[int64]Migration{}
)

// Register adds a migration to the global registry. It panics on a missing Up
// or a duplicate version, since either is a programming error that would
// otherwise surface as a silently skipped migration.
func Register(m Migration) {
	mu.Lock()
	defer mu.Unlock()
	if m.Up == nil {
		panic(fmt.Sprintf("migrate: migration %d (%s) has no Up", m.Version, m.Name))
	}
	if prev, ok := registry[m.Version]; ok {
		panic(fmt.Sprintf("migrate: duplicate version %d (%s and %s)", m.Version, prev.Name, m.Name))
	}
	registry[m.Version] = m
}

// Registered returns every registered migration, oldest first.
func Registered() []Migration {
	mu.Lock()
	defer mu.Unlock()
	out := make([]Migration, 0, len(registry))
	for _, m := range registry {
		out = append(out, m)
	}
	sortMigrations(out)
	return out
}

func sortMigrations(ms []Migration) {
	sort.Slice(ms, func(i, j int) bool { return ms[i].Version < ms[j].Version })
}
